// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(address caller, uint256 v1) public {
        if (caller == address(0)) caller = address(1);

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        bool ok1;
        try c.SetMinSum(v1) { ok1 = true; } catch { ok1 = false; }

        vm.prank(caller);
        bool ok2;
        try c.SetMinSum(v1) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2);
    }
}
